int main(void)
{
    int *a;
    int i, sum = 0;
    cls();
    a = malloc(10 * sizeof(int));
    if (a == 0) {
        print("no room");
        return -1;
    }
    for (i = 0; i < 10; i++) {
        a[i] = i;
        sum += a[i];
    }
    printf("sum %d\n", sum);
    printf("%d", malloc(40000) == 0);
    free(a);
    return sum;
}
